let language='tl', bank=[], selected=[], submitted=false, quote='', questionDeck=[];
const ui={exam:document.querySelector('#exam'),lang:document.querySelector('#lang'),submit:document.querySelector('#submit'),score:document.querySelector('#score'),progress:document.querySelector('#progress'),reset:document.querySelector('#reset'),title:document.querySelector('#title'),eyebrow:document.querySelector('#eyebrow')};
const t={en:{title:'Ready to practice?',sub:'Pop quiz energy, but at least the chairs are imaginary.',lang:'Translate to Tagalog',newSet:'New random set',submit:'Check answers',picked:'10 questions selected',score:(n)=>`Score: ${n}/10`},tl:{title:'Handa ka nang magsanay?',sub:'Parang recitation, pero hindi ka tatawagin sa unahan.',lang:'Translate to English',newSet:'Bagong random na set',submit:'Suriin ang mga sagot',picked:'10 napiling tanong',score:(n)=>`Iskor: ${n}/10`}};
const quotes=['“2nd thoughts are 80% wrong.” - Sir T','“Kill them first before they kill you.” - Sir T','“You da MAN” - Sir T','“How sure you are?” - Ginoong Orosco','“Oh Em Gee” - Dr Singsong','“My Family” - Dr Sombrero','“Make us holy” - Sir T'];
function shuffle(a){const copy=[...a];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function nextQuestions(){if(questionDeck.length<10)questionDeck=shuffle(bank);return questionDeck.splice(0,10)}
function buildBank(data){return data.topics.flatMap((q,topic)=>Array.from({length:data.variantsPerTopic},(_,variant)=>({...q,id:`${topic}-${variant}`,variant,en:variant===0?q.en:variant===1?`According to the reviewer, ${q.en.charAt(0).toLowerCase()}${q.en.slice(1)}`:variant===2?`Choose the best answer: ${q.en}`:`Which statement from the reviewer is accurate? ${q.en}`,tl:variant===0?q.tl:variant===1?`Ayon sa reviewer, ${q.tl.charAt(0).toLowerCase()}${q.tl.slice(1)}`:variant===2?`Piliin ang pinakamainam na sagot: ${q.tl}`:`Aling pahayag mula sa reviewer ang wasto? ${q.tl}`})));}
function options(q){return shuffle([{en:q.correct,tl:q.correctTl,right:true},...q.wrong.map((x,i)=>({en:x,tl:q.wrongTl[i],right:false}))]);}
function render(){submitted=false;quote=shuffle(quotes)[0];ui.submit.disabled=false;ui.score.textContent='';ui.exam.innerHTML='';selected=nextQuestions().map(q=>({...q,options:options(q)}));selected.forEach((q,i)=>{let node=document.querySelector('#question').content.cloneNode(true);let card=node.querySelector('.question');card.dataset.id=q.id;node.querySelector('.number').textContent=String(i+1).padStart(2,'0');node.querySelector('h2').textContent=q[language];let box=node.querySelector('.options');q.options.forEach((o,j)=>{let l=document.createElement('label');l.className='option';l.innerHTML=`<input type="radio" name="q${i}" value="${j}"><span>${o[language]}</span>`;box.append(l)});ui.exam.append(node)});copy();}
function copy(){let s=t[language];document.documentElement.lang=language;ui.title.textContent=quote;ui.lang.textContent=s.lang;ui.reset.textContent=s.newSet;ui.submit.textContent=s.submit;ui.progress.textContent=`${s.picked} · ${bank.length} question bank`;}
function translate(){copy();selected.forEach((q,i)=>{let card=ui.exam.children[i];card.querySelector('h2').textContent=q[language];q.options.forEach((o,j)=>card.querySelector(`input[value="${j}"]`).nextElementSibling.textContent=o[language]);if(submitted){let pick=card.querySelector(`input[name=q${i}]:checked`);let fb=card.querySelector('.feedback');fb.querySelector('strong').textContent=(pick&&q.options[pick.value].right)?(language==='en'?'Correct':'Tama'):(language==='en'?'Review this one':'Balikan ito');fb.querySelector('p').textContent=language==='en'?q.ex:q.exTl;}});}
function grade(){if(submitted)return;submitted=true;let total=0;selected.forEach((q,i)=>{let card=ui.exam.children[i], pick=card.querySelector(`input[name=q${i}]:checked`);q.options.forEach((o,j)=>{let label=card.querySelector(`input[value="${j}"]`).closest('label');label.classList.add(o.right?'correct':pick?.value==j?'wrong':'dim');label.querySelector('input').disabled=true});if(pick&&q.options[pick.value].right)total++;let fb=card.querySelector('.feedback');fb.hidden=false;fb.querySelector('strong').textContent=(pick&&q.options[pick.value].right)?(language==='en'?'Correct':'Tama'):(language==='en'?'Review this one':'Balikan ito');fb.querySelector('p').textContent=language==='en'?q.ex:q.exTl;});ui.score.textContent=t[language].score(total);ui.submit.disabled=true;window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'});}
const sourceFiles=['quiz3a','quiz3b','quiz3c','quiz4a','quiz4b','quiz4c'];
Promise.all(sourceFiles.map(name=>fetch(`question-sources/${name}.json?v=modified-tf-1`).then(r=>r.json()))).then(files=>{bank=files.flatMap(file=>file.questions);if(bank.length!==120)throw new Error(`Expected 120 quiz questions, found ${bank.length}`);render()});ui.lang.onclick=()=>{language=language==='en'?'tl':'en';translate()};ui.reset.onclick=render;ui.submit.onclick=grade;
